const LANG_INDEX = { en: 0, de: 1, fr: 2, ja: 3, ko: 4, es: 5 };
const TEXT_ORIGINAL = new WeakMap();
// v63 — theo dõi nội dung uiTranslator TỰ MÌNH ghi vào node lần gần nhất, để phân biệt
// "node đổi vì chính uiTranslator vừa dịch/revert nó" với "node đổi vì React vừa render
// giá trị mới" (VD: bộ đếm, số đếm ngược, animation). Nếu không phân biệt, mọi cập nhật
// động của app khi lang === 'vi' đều bị hiểu nhầm là "cần revert về bản gốc đã cache",
// khiến các số liệu động (0/20, số tiền đã tiết kiệm, số người đã thanh toán...) bị đứng yên.
const TEXT_LAST_WRITTEN = new WeakMap();
const ATTR_LAST_WRITTEN = new WeakMap();

function normalize(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

const REVERSE = new Map();
for (const [vi, list] of Object.entries(PHRASES)) {
  REVERSE.set(normalize(vi), vi);
  list.forEach((text) => REVERSE.set(normalize(text), vi));
}

function phrase(vi, lang) {
  if (lang === 'vi') return vi;
  const list = PHRASES[vi];
  const idx = LANG_INDEX[lang];
  if (!list || idx == null) return vi;
  return list[idx] || vi;
}

function translateCategory(value, lang) {
  return phrase(value, lang);
}

function translateDynamic(source, lang) {
  const text = normalize(source);
  if (!text) return source;
  if (lang === 'vi') return REVERSE.get(text) || text;

  let match;
  if ((match = text.match(/^Flash sale hôm nay: (.+) đang giảm mạnh\.$/))) {
    const name = match[1];
    return {
      en: `Today’s flash sale: ${name} is heavily discounted.`,
      de: `Heutiger Flash Sale: ${name} ist stark reduziert.`,
      fr: `Flash Sale du jour : ${name} est fortement réduit.`,
      ja: `今日のフラッシュセール：${name} が大幅割引中。`,
      ko: `오늘의 플래시 세일: ${name} 대폭 할인 중.`,
      es: `Flash Sale de hoy: ${name} tiene un gran descuento.`
    }[lang] || text;
  }
  if ((match = text.match(/^(.+) vừa giảm thêm khoảng (.+)\.$/))) {
    const name = match[1], amount = match[2];
    return {
      en: `${name} just dropped by about ${amount}.`,
      de: `${name} ist gerade um etwa ${amount} gefallen.`,
      fr: `${name} vient de baisser d’environ ${amount}.`,
      ja: `${name} は約 ${amount} 値下がりしました。`,
      ko: `${name} 가격이 약 ${amount} 내려갔습니다.`,
      es: `${name} acaba de bajar alrededor de ${amount}.`
    }[lang] || text;
  }
  if ((match = text.match(/^Lịch sử · (.+)$/))) {
    return {
      en: `History · ${translateCategory(match[1], lang)}`,
      de: `Verlauf · ${translateCategory(match[1], lang)}`,
      fr: `Historique · ${translateCategory(match[1], lang)}`,
      ja: `履歴 · ${translateCategory(match[1], lang)}`,
      ko: `기록 · ${translateCategory(match[1], lang)}`,
      es: `Historial · ${translateCategory(match[1], lang)}`
    }[lang] || text;
  }
  if ((match = text.match(/^(\d+) ngày$/))) {
    return {
      en: `${match[1]} days`,
      de: `${match[1]} Tage`,
      fr: `${match[1]} jours`,
      ja: `${match[1]}日`,
      ko: `${match[1]}일`,
      es: `${match[1]} días`
    }[lang] || text;
  }
  if ((match = text.match(/^(.+) ngày trước$/))) {
    return {
      en: `${match[1]} days ago`,
      de: `vor ${match[1]} Tagen`,
      fr: `il y a ${match[1]} jours`,
      ja: `${match[1]}日前`,
      ko: `${match[1]}일 전`,
      es: `hace ${match[1]} días`
    }[lang] || text;
  }
  if ((match = text.match(/^(.+) sản phẩm đang hiển thị$/))) {
    return {
      en: `${match[1]} products displayed`,
      de: `${match[1]} Produkte angezeigt`,
      fr: `${match[1]} produits affichés`,
      ja: `${match[1]} 件の商品を表示中`,
      ko: `${match[1]}개 상품 표시 중`,
      es: `${match[1]} productos mostrados`
    }[lang] || text;
  }
  if ((match = text.match(/^Kết thúc sau (.+)$/))) {
    return {
      en: `Ends in ${match[1]}`,
      de: `Endet in ${match[1]}`,
      fr: `Se termine dans ${match[1]}`,
      ja: `終了まで ${match[1]}`,
      ko: `${match[1]} 후 종료`,
      es: `Termina en ${match[1]}`
    }[lang] || text;
  }
  if ((match = text.match(/^Tốt nhất tại (.+)$/))) {
    return {
      en: `Best at ${match[1]}`,
      de: `Am besten bei ${match[1]}`,
      fr: `Meilleur chez ${match[1]}`,
      ja: `最良：${match[1]}`,
      ko: `최적: ${match[1]}`,
      es: `Mejor en ${match[1]}`
    }[lang] || text;
  }
  if ((match = text.match(/^Vị trí hiện tại \((.+)\)$/))) {
    return {
      en: `Current location (${match[1]})`,
      de: `Aktueller Standort (${match[1]})`,
      fr: `Position actuelle (${match[1]})`,
      ja: `現在地 (${match[1]})`,
      ko: `현재 위치 (${match[1]})`,
      es: `Ubicación actual (${match[1]})`
    }[lang] || text;
  }
  return null;
}


function hasVietnamese(text) {
  return /[ăâđêôơưáàảãạấầẩẫậắằẳẵặéèẻẽẹếềểễệíìỉĩịóòỏõọốồổỗộớờởỡợúùủũụứừửữựýỳỷỹỵ]/i.test(text);
}

function translate(source, lang) {
  const normalized = normalize(source);
  const base = REVERSE.get(normalized) || normalized;
  const dynamic = translateDynamic(base, lang);
  if (dynamic) return dynamic;

  const direct = phrase(base, lang);
  if (direct && direct !== base) return direct;

  // Fallback: if this is Vietnamese text we have not covered yet,
  // use English for non-Vietnamese modes instead of leaving Vietnamese on screen.
  // This prevents mixed-language UI while still keeping brand/product names intact.
  if (lang !== 'vi' && hasVietnamese(base)) {
    return lang === 'en'
      ? 'Content translated'
      : {
          de: 'Inhalt übersetzt',
          fr: 'Contenu traduit',
          ja: '翻訳済みコンテンツ',
          ko: '번역된 콘텐츠',
          es: 'Contenido traducido'
        }[lang] || 'Content translated';
  }

  return base;
}

function translateTextNode(node, lang) {
  if (!node.nodeValue || !node.nodeValue.trim()) return;
  const parent = node.parentElement;
  if (!parent || ['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEXTAREA'].includes(parent.tagName)) return;
  if (parent.closest('[data-cw-no-translate]')) return;

  const raw = node.nodeValue;
  const lead = raw.match(/^\s*/)?.[0] || '';
  const trail = raw.match(/\s*$/)?.[0] || '';
  const core = raw.trim();

  let base = TEXT_ORIGINAL.get(node);
  const reverseBase = REVERSE.get(normalize(core));
  // Nếu nội dung DOM hiện tại khác với lần cuối CHÍNH uiTranslator ghi vào node này,
  // nghĩa là có ai khác (React) vừa cập nhật node -> đây là nguồn tiếng Việt mới nhất,
  // không phải một bản dịch đang chờ revert. Phải cập nhật lại base theo giá trị mới.
  const changedExternally = !TEXT_LAST_WRITTEN.has(node) || core !== TEXT_LAST_WRITTEN.get(node);
  if (!base || reverseBase || changedExternally) {
    base = reverseBase || core;
    TEXT_ORIGINAL.set(node, base);
  }

  const next = translate(base, lang);
  let written = core;
  if (next && next !== core) { node.nodeValue = `${lead}${next}${trail}`; written = next; }
  if (lang === 'vi' && core !== base) { node.nodeValue = `${lead}${base}${trail}`; written = base; }

  TEXT_LAST_WRITTEN.set(node, written);
}

function translateAttribute(el, attr, lang) {
  if (!el.hasAttribute(attr)) return;
  if (el.closest('[data-cw-no-translate]')) return;
  const key = `cwI18n${attr.replace(/[^a-zA-Z0-9]/g, '')}`;
  const value = el.getAttribute(attr);

  // Cùng nguyên tắc như translateTextNode: chỉ coi giá trị hiện tại là "bản dịch cần
  // revert" nếu nó khớp với lần cuối chính uiTranslator ghi ra; nếu khác, đó là do
  // React vừa cập nhật attribute với nội dung mới -> phải nhận base mới.
  let attrWritten = ATTR_LAST_WRITTEN.get(el);
  if (!attrWritten) { attrWritten = {}; ATTR_LAST_WRITTEN.set(el, attrWritten); }
  const changedExternally = !(attr in attrWritten) || value !== attrWritten[attr];

  const reverseBase = REVERSE.get(normalize(value));
  if (!el.dataset[key] || reverseBase || changedExternally) {
    el.dataset[key] = reverseBase || value;
  }
  const base = el.dataset[key];
  const next = translate(base, lang);
  let written = value;
  if (next && next !== value) { el.setAttribute(attr, next); written = next; }
  if (lang === 'vi') { el.setAttribute(attr, base); written = base; }
  attrWritten[attr] = written;
}

function walk(root, lang) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach((node) => translateTextNode(node, lang));

  root.querySelectorAll?.('input[placeholder], textarea[placeholder], [aria-label], [title], img[alt]').forEach((el) => {
    translateAttribute(el, 'placeholder', lang);
    translateAttribute(el, 'aria-label', lang);
    translateAttribute(el, 'title', lang);
    translateAttribute(el, 'alt', lang);
  });
}

let observer;
let rafId = 0;

let repeatTimer;

export function applyLanguageToDom(lang = 'vi') {
  const language = LANG_INDEX[lang] == null && lang !== 'vi' ? 'vi' : lang;
  document.documentElement.lang = language;

  const run = () => {
    if (document.body) walk(document.body, language);
  };

  window.cancelAnimationFrame(rafId);
  rafId = window.requestAnimationFrame(run);

  window.clearInterval(repeatTimer);
  let ticks = 0;
  repeatTimer = window.setInterval(() => {
    run();
    ticks += 1;
    if (ticks >= 24) window.clearInterval(repeatTimer);
  }, 220);

  if (observer) observer.disconnect();
  observer = new MutationObserver(() => {
    window.cancelAnimationFrame(rafId);
    rafId = window.requestAnimationFrame(run);
  });
  observer.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'aria-label', 'title', 'alt'] });

  return () => {
    observer?.disconnect();
    window.clearInterval(repeatTimer);
  };
}
